/* START Scorecard Styles */

.scorecard {
    background: rgba(255, 255, 255, 0.9);
    border: 1px solid rgba(0, 0, 0, 0.1);
    padding: 20px;
    box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
    width: 90%;
    max-width: 550px;
    text-align: center;
    overflow-y: auto;
}

.scorecard h1 {
    font-size: 2em;
    color: #004b87;
    margin-bottom: 10px;
}

.scorecard h2 {
    font-size: 1.5em;
    color: #004b87;
    margin-bottom: 5px;
}

.scorecard p {
    margin-bottom: 10px;
    color: #00355e;
    position: relative;
}

.scores {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 10px;
    justify-content: center;
    align-items: center;
    position: relative;
    z-index: 1;
    /* Ensure this is lower than .info-icon-scorecard */
}

.score-item {
    display: flex;
    align-items: center;
    background: rgba(255, 255, 255, 0.9);
    background-image: linear-gradient(45deg, #f0f0f0, transparent);
    border: 1px solid rgba(0, 0, 0, 0.1);
    padding: 10px;
    border-radius: 10px;
    transition: transform 0.3s ease, background 0.3s ease;
    width: 100%;
    max-width: 250px;
    height: 60px;
    justify-content: space-between;
    position: relative;
    overflow: visible;
    z-index: 1
}

.score-item:hover {
    transform: translateY(-5px);
    background-image: linear-gradient(45deg, transparent, #f0f0f0);
}

.score {
    color: white;
    padding: 10px;
    border-radius: 5px;
    font-size: 1.5em;
    width: 50px;
    text-align: center;
}

.score.green {
    background: #4CAF50;
}

.score.yellow {
    background: #FFEB3B;
    color: black;
}

.score.red {
    background: #f44336;
}

.score-name {
    flex-grow: 1;
    text-align: left;
    padding-left: 10px;
    font-size: 1.2em;
}

.logo-image-scorecard {
    width: 100px;
}

.info-icon-scorecard {
    position: relative;
    cursor: pointer;
}

.info-icon-scorecard:hover::after {
    content: attr(data-info);
    position: fixed;
    top: 30px;
    left: 50%;
    transform: translateX(-50%);
    background-color: #444444eb;
    color: #fff;
    padding: 10px;
    border-radius: 5px;
    width: 200px;
    text-align: left;
    box-shadow: 0 2px 5px rgba(0, 0, 0, 0.3);
    font-size: 12px;
    white-space: normal;
    z-index: 1000;
}

@media (max-width: 768px) {
    .scores {
        grid-template-columns: 1fr;
    }
    .score-item {
        max-width: 90%;
        height: auto;
        flex-direction: column;
        justify-content: center;
        text-align: center;
        position: relative;
        overflow: visible;
        z-index: 1;
    }
    .score {
        width: auto;
    }
    .info-icon-scorecard:hover::after {
        width: 150px;
        top: 20px;
    }
}

/* END Scorecard Styles */

@media print {
    .NodeTypeArticle--sidebar,
    .NodeTypeReview--sidebar {
        display: none
    }
    ul.breadcrumbs {
        display: none !important
    }
    .Node--comments,
    #disqus_thread,
    #header .navigation,
    .Footer--root,
    .meta-runner,
    .SiteFooterDisclosure--root,
    .disclosure {
        display: none
    }
}

/**
 * @file
 * Styles for system messages.
 */

div.messages {
    background-position: 8px 8px;
    /* LTR */
    background-repeat: no-repeat;
    border: 1px solid;
    margin: 6px 0;
    padding: 10px 10px 10px 50px;
    /* LTR */
}

div.status {
    background-image: url(../../misc/message-24-ok.png);
    border-color: #be7;
}

div.status,
.ok {
    color: #234600;
}

div.status,
table tr.ok {
    background-color: #f8fff0;
}

div.warning {
    background-image: url(../../misc/message-24-warning.png);
    border-color: #ed5;
}

div.warning,
.warning {
    color: #840;
}

div.warning,
table tr.warning {
    background-color: #fffce5;
}

div.error {
    background-image: url(../../misc/message-24-error.png);
    border-color: #ed541d;
}

div.error,
.error {
    color: #8c2e0b;
}

div.error,
table tr.error {
    background-color: #fef5f1;
}

